def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "vacuum_hair": And([
            Not(self.pet_food_disposed()),
            self.object_at(self.pet_food, self.pet_bed),
            self.robot_equipped_with_vacuum,
            self.manual_sorting_available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
